 e di non poter forse venire.","fr":"Un invité dit séjourner chez des gens à Greenwich et ne pas pouvoir forcément venir.","es":"Un invitado dice que se aloja con unas personas en Greenwich y quizá no pueda ir."}}},{"book":"gatsby","id":"hempstead","collection":"cited","name":"Hempstead","noteHash":"1e65335f06f936602032d7b068584b05","positionSource":"f2bb6e8d107dbe2da5b134af0c9ec4be6e567e21ed2086fe929539ee1d52bb88","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Jordan telephones from Hempstead after leaving Daisy’s house.","it":"Jordan telefona da Hempstead dopo aver lasciato la casa di Daisy.","fr":"Jordan téléphone de Hempstead après avoir quitté la maison de Daisy.","es":"Jordan llama desde Hempstead después de dejar la casa de Daisy."}}},{"book":"gatsby","id":"montreal","collection":"cited","name":"Montreal","noteHash":"1e65335f06f936602032d7b068584b05","positionSource":"225cd2417ee56bcaf677559de603574aef00bcd1da634c7ec7d6f2c7720da7d5","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Montreal is suggested alongside Atlantic City as a place to visit for a week.","it":"Montreal è suggerita insieme ad Atlantic City come meta per un viaggio di una settimana.","fr":"Montréal est suggérée avec Atlantic City comme destination pour un voyage d’une semaine.","es":"Montreal se propone junto con Atlantic City como destino para un viaje de una semana."}}}]'::jsonb; expected integer := 18;
begin
 if (select count(*) from public.place_descriptions d join jsonb_to_recordset(p) x(book text,id text,collection text,"noteHash" text,"positionSource" text,"narrativeSource" text,description jsonb) on d.book_id=x.book and d.place_id=x.id and d.collection=x.collection where md5(coalesce(d.note,''))=x."noteHash" and d.position_source_id::text=x."positionSource" and d.narrative_source_id::text is not distinct from x."narrativeSource" and (not (coalesce(d.metadata,'{}'::jsonb) ? 'positionDescription') or d.metadata->'positionDescription'=x.description)) <> expected then raise exception 'A source or summary changed; no updates applied'; end if;
 update public.place_descriptions d set metadata=jsonb_set(coalesce(d.metadata,'{}'::jsonb),'{positionDescription}',x.description,true) from jsonb_to_recordset(p) x(book text,id text,collection text,description jsonb) where d.book_id=x.book and d.place_id=x.id and d.collection=x.collection;
end $revision$;
